      "aHash": "25902c4d2d8b9ae93c8d4ee963bfb9c19c2938eb42eb484f7d00ab9b2a4d27ff",
      "canonicalId": "ECON-SP-INTERPRET-SACRIFICE-RATIO-6051",
      "primaryConceptId": "sacrifice-ratio",
      "secondaryConceptIds": [
        "disinflation-and-policy"
      ],
      "instructionalRole": "bridge",
      "canonicalDifficulty": "medium",
